mapper.sql:
FROM content c JOIN content_revision r ON r.id = c.published_revision_idcoalesce(c.working_revision_id,c.published_revision_id)
c.publish_status='published' AND c.deleted_at IS NULL c.deleted_at IS NOT NULL c.deleted_at IS NULL AND c.working_revision_id IS NOT NULL AND c.publish_status='published' AND c.publish_status='offline'
AND c.content_type=#{type} AND EXISTS(SELECT 1 FROM site_setting s WHERE s.setting_key='site.public' AND jsonb_exists(s.value_jsonb->'homeModules',c.content_type)) AND (r.title ILIKE #{search} ESCAPE '!' OR r.summary ILIKE #{search} ESCAPE '!' OR EXISTS(SELECT 1 FROM revision_tag rt JOIN tag t ON t.id=rt.tag_id WHERE rt.revision_id=r.id AND t.name ILIKE #{search} ESCAPE '!')) AND r.category_id=#{categoryId} AND EXISTS(SELECT 1 FROM revision_tag rt WHERE rt.revision_id=r.id AND rt.tag_id=#{tagId}) AND (c.first_published_at AT TIME ZONE 'Asia/Shanghai')::date=#{date}
